import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.BXzK3EA4.js";const m=JSON.parse('{"title":"이 시대의 기술과 무구","description":"","frontmatter":{},"headers":[],"relativePath":"world/Era-Arms-and-Tech-Level.md","filePath":"world/Era-Arms-and-Tech-Level.md"}'),o={name:"world/Era-Arms-and-Tech-Level.md"};function h(l,t,i,n,c,s){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="이-시대의-기술과-무구" tabindex="-1">이 시대의 기술과 무구 <a class="header-anchor" href="#이-시대의-기술과-무구" aria-label="Permalink to &quot;이 시대의 기술과 무구&quot;">​</a></h1><p>붕괴 이후 서울에서 사람이 손에 쥐는 것은 병과 표가 아니라 생업 도구, 치안 제식, 군용 잔존, 로스트 테크 회수품이다. 이 페이지는 그 구멍을 메우는 <strong>설계 제안</strong>이다. <a href="/world/Starting-Presets.html">시작 프리셋</a>과 같이, 아래 수치는 목표값이지 구현 완료가 아니다.</p><p>Core 전투의 <code>근위</code>·<code>돌격</code>·<code>궁수</code>는 세계 기획이 아니다. 시뮬 스캐폴드다.</p><h2 id="출처를-나누는-법" tabindex="-1">출처를 나누는 법 <a class="header-anchor" href="#출처를-나누는-법" aria-label="Permalink to &quot;출처를 나누는 법&quot;">​</a></h2><table tabindex="0"><thead><tr><th>층</th><th>쓰는 곳</th><th>쓰지 않는 곳</th></tr></thead><tbody><tr><td>세계 정본</td><td>생업, 상대 연혁, 탄약을 보급으로 두는 규칙, 로스트 테크 세 라인</td><td>서기 붕괴 연도, 개인 병기 카탈로그</td></tr><tr><td>2026 사실</td><td>한국에서 민간이 총을 못 들고, 국군 제식 소총이 있으며, 석궁도 허가 대상인 점</td><td>붕괴 이후 총기가 흔하다는 추론</td></tr><tr><td>레퍼런스 논리</td><td>결핍의 종류, 회수 부품, 보급에 따른 혼성 무장</td><td>폴아웃·호라이즌·전국 고유명, 활을 기본 무기로 넣는 일</td></tr></tbody></table><p>공개 페이지는 원작 군복·문장·고유 병기를 재현하지 않는다. <a href="/design/Unofficial-Fan-AU-Notice.html">비공식 팬 AU 고지</a></p><h2 id="연혁-—-정본은-상대-시간만-둔다" tabindex="-1">연혁 — 정본은 상대 시간만 둔다 <a class="header-anchor" href="#연혁-—-정본은-상대-시간만-둔다" aria-label="Permalink to &quot;연혁 — 정본은 상대 시간만 둔다&quot;">​</a></h2><p><a href="/world/Scenario-Timeline.html">시나리오 타임라인</a>은 서기 연도를 적지 않는다.</p><table tabindex="0"><thead><tr><th>상대 시각</th><th>사건</th><th>줄</th></tr></thead><tbody><tr><td>붕괴 5년 전</td><td>연결된 도시</td><td><code>:9</code></td></tr><tr><td>붕괴 0년</td><td>대정전</td><td><code>:18</code></td></tr><tr><td>붕괴 1–5년</td><td>급수협약, 열여섯 깃발, 둘째 급수협약</td><td><code>:29–65</code></td></tr><tr><td>개막일</td><td>세 번째 급수계약. 붕괴 5년 <strong>다음</strong> 사건이지 붕괴 6년이라고 적히지 않았다</td><td><code>:74–76</code></td></tr></tbody></table><p>2026년 기술 수준의 서울에서, 그 <strong>이후</strong> 근미래에 붕괴가 난다는 앵커는 이 페이지의 제안이다. 정본에 서기 붕괴 연도가 없다. <code>2030년대</code>를 정본처럼 쓰지 않는다. 개막이 붕괴 몇 년 뒤인지도 문서가 숫자를 안 적는다. <strong>UNVERIFIED.</strong></p><h2 id="_2026년에-실제로-있는-것" tabindex="-1">2026년에 실제로 있는 것 <a class="header-anchor" href="#_2026년에-실제로-있는-것" aria-label="Permalink to &quot;2026년에 실제로 있는 것&quot;">​</a></h2><p>열람일 2026-09-11. 붕괴 이후 허구가 아니라, 근미래 잔존의 출발점이다.</p><ul><li>총포화약법 제1조: 총포·도검·화약류·분사기·전자충격기·<strong>석궁</strong>의 제조·판매·임대·운반·소지·사용을 정한다. 시행 2026. 1. 8. 민간이 총을 일상으로 드는 나라가 아니다. (<a href="https://www.law.go.kr/LSW/lsSc.do?menuId=1&amp;query=%EC%B4%9D%ED%8F%AC%C2%B7%EB%8F%84%EA%B2%80%C2%B7%ED%99%94%EC%95%BD%EB%A5%98" target="_blank" rel="noreferrer">국가법령정보센터</a>, 캡처 <code>.omo/ulw-research/20260911-200129/browse/01-law-go-kr-firearms-swords.png</code>)</li><li>K2는 대한민국 국군 제식 돌격소총이며 1985년부터 현재까지 쓰인다. 잔존한다면 군 창고·탈영·군벌 쪽이지 대합실 상점이 아니다. (<a href="https://en.wikipedia.org/wiki/Daewoo_Precision_Industries_K2" target="_blank" rel="noreferrer">영문 위키, Daewoo K2</a>, 캡처 <code>browse/04-k2-wikipedia.png</code>)</li><li>즉석 화기는 배관·공구로 단발을 만드는 현실 범주다. 게임 고유명이 아니다. (<a href="https://en.wikipedia.org/wiki/Improvised_firearm" target="_blank" rel="noreferrer">Improvised firearm</a>)</li></ul><p>치안 쪽 제식 봉·방패는 정본 프리셋이 이미 「제식 봉·순찰 방패」로 적는다. 2026 경찰 장비 세칙 원문은 이 런에서 조문 전문을 못 열었다. 세칙 숫자는 잠그지 않는다.</p><h2 id="네-층" tabindex="-1">네 층 <a class="header-anchor" href="#네-층" aria-label="Permalink to &quot;네 층&quot;">​</a></h2><p>사람이 싸우는 단위는 <a href="/world/Characters-Factions-and-Professions.html">인물·세력·생업</a>의 생업 일곱이다. 정비사, 물류상, 의무원, 순찰대, 전령, 탐사원, 기록관. 전술 기여는 장치 해제, 진형 유지, 함정 탐지다. 병과가 아니다.</p><table tabindex="0"><thead><tr><th>층</th><th>손에 쥐는 것</th><th>어디서 오나</th><th>탄약</th></tr></thead><tbody><tr><td>생업 공구</td><td>봉, 지렛대, 랜턴, 공구</td><td>역 공사장, 차량기지, 배전실</td><td>없음</td></tr><tr><td>치안 제식</td><td>제식 봉, 순찰 방패, 응급 키트</td><td>자치 순찰, 역 경비</td><td>없음</td></tr><tr><td>군용 잔존</td><td>이름 없는 제식 소화기·방호구</td><td>군벌, 탈영, 봉인된 무기고</td><td>물자점 재고. 부족하면 출격 수가 줄어든다</td></tr><tr><td>로스트 회수</td><td>축전·구동·센서 모듈, 프로토콜 카드</td><td>방재 로봇 해체</td><td>총알이 아니다</td></tr></tbody></table><p>아트 실루엣은 이미 잠겨 있다. 탐사원 지렛대·랜턴·안테나, 의무원 붉은 천, 순찰대 방패등. (<a href="/rules/Character-Art-Direction.html">캐릭터 미술</a> <code>:46</code>)</p><p>탄약은 식량과 묶인 보급일이다. 주민 노동을 깎지 않고 전술 장비와 출격 수량만 줄인다. (<a href="/world/Economy-and-Production.html">경제와 생산</a> <code>:15</code>, <code>:80</code>; <a href="/rules/Warfare-and-Sieges.html">전쟁과 공성</a> <code>:58</code>)</p><p>총기로 야생 무리를 쓸어 담는 일은 최후 수단이다. (<a href="/world/Hostile-Ecology-Index.html">적대 생태 색인</a> <code>:56</code>)</p><h2 id="누가-무엇을-드나" tabindex="-1">누가 무엇을 드나 <a class="header-anchor" href="#누가-무엇을-드나" aria-label="Permalink to &quot;누가 무엇을 드나&quot;">​</a></h2><p><a href="/world/Starting-Presets.html">시작 프리셋</a>은 기능 목록이 아니다. 결핍의 종류다. 접근만 이렇게 읽는다.</p><table tabindex="0"><thead><tr><th>시점</th><th>생업 공구</th><th>치안 제식</th><th>군용 잔존</th><th>로스트 모듈</th></tr></thead><tbody><tr><td>떠돌이</td><td>봉·낡은 의복</td><td>없음</td><td>없음</td><td>없음</td></tr><tr><td>전직 순찰</td><td>있음</td><td>제식 봉·방패</td><td>없음</td><td>없음</td></tr><tr><td>상인</td><td>카트·저울</td><td>없음</td><td>없음. 싸우지 않음</td><td>거래만</td></tr><tr><td>탈영 소대</td><td>있음</td><td>있음</td><td>제식 무기. 눈에 띈다</td><td>없음</td></tr><tr><td>고아 무리</td><td>넝마</td><td>없음</td><td>없음</td><td>없음</td></tr><tr><td>역장</td><td>거점 공구</td><td>게시판·경비</td><td>거점 잠금</td><td>거점이 열면</td></tr></tbody></table><p>역장은 프리셋 장비 칸이 비어 있다. 거점 열쇠로 층을 연다는 뜻이지, 처음부터 소총을 든다는 뜻이 아니다.</p><p>프리셋의 「신도림 자치회」「구로 군벌」은 <a href="/world/Sixteen-States.html">서울 십육국</a> 국명과 아직 맞물리지 않는다. 구로 권역은 서남제작동맹이고, 그 군사는 공병대·차단문 전투조다. 탈영 소대의 「제식 무기」를 K2로 읽지 않는다.</p><p>십육국 「군사」는 수문 경비대, 공병대, 차단문 전투조, 궤도기병대처럼 <strong>시설을 지키는 조직 이름</strong>이다. (<a href="/world/Sixteen-States.html">서울 십육국</a> <code>:80</code>, <code>:94</code>, <code>:222</code>) 근위·돌격·궁수가 아니다.</p><h2 id="로스트-테크는-개인-병기가-아니다" tabindex="-1">로스트 테크는 개인 병기가 아니다 <a class="header-anchor" href="#로스트-테크는-개인-병기가-아니다" aria-label="Permalink to &quot;로스트 테크는 개인 병기가 아니다&quot;">​</a></h2><p>붕괴 전 방재 로봇이 수색·보강·관로 검사 명령을 반복한다. (<a href="/world/Lost-Technology-Lineage.html">로스트 테크 계보</a> <code>:4–8</code>) 사람은 재기동 지점을 점거하고 모듈을 떼거나, 프로토콜 카드로 멈춘다. 활로 공룡을 사냥하는 그림이 아니다.</p><p>호라이즌에서 가져올 것은 「기계를 쓰러뜨린 뒤 부품을 쓴다」는 경제다. 가져오면 안 되는 것은 원시 부족의 활이다. 잔선 사람은 2026 서울 사람이다.</p><h2 id="레퍼런스에서-가져올-것-버릴-것" tabindex="-1">레퍼런스에서 가져올 것 / 버릴 것 <a class="header-anchor" href="#레퍼런스에서-가져올-것-버릴-것" aria-label="Permalink to &quot;레퍼런스에서 가져올 것 / 버릴 것&quot;">​</a></h2><p>세 작품은 <a href="/design/Game-References.html">레퍼런스 게임 조사</a>의 논리 재료다. 세계 지리가 아니다.</p><table tabindex="0"><thead><tr><th>축</th><th>가져올 것</th><th>버릴 것</th></tr></thead><tbody><tr><td>전국·삼국</td><td>보급이 다른 혼성 무장, 지급품과 노획품의 차이, 진형</td><td>활을 서울 기본 병과로 두는 일, 무사 신분</td></tr><tr><td>폴아웃</td><td>결핍이 동사별로 갈린다. 탄약은 출격을 줄인다. 배관·공구가 밑바닥 무기</td><td>미국 총기 문화, 핵 복고, 고유 병기명, 병뚜껑 화폐</td></tr><tr><td>호라이즌</td><td>기계는 적이자 자원. 산 채로 멈추는 편이 해체 이득</td><td>활·창이 기본, 부족 사냥 의례</td></tr></tbody></table><p>아시가루가 창과 철포를 섞어 든 것은 보급 이야기다. 서울 대합실에 조총을 놓으라는 뜻이 아니다. (<a href="https://en.wikipedia.org/wiki/Ashigaru" target="_blank" rel="noreferrer">Ashigaru</a>, <a href="https://en.wikipedia.org/wiki/Tanegashima_(gun)" target="_blank" rel="noreferrer">Tanegashima</a>, 열람 2026-09-11)</p><p>전투 카드의 출처는 관계·생업·특기와 거점(보급·통행권·설비)이다. (<a href="/rules/Realtime-Formation-Card-Battle.html">실시간 진형·카드 전투</a> <code>:72</code>)</p><h2 id="넣지-말-것" tabindex="-1">넣지 말 것 <a class="header-anchor" href="#넣지-말-것" aria-label="Permalink to &quot;넣지 말 것&quot;">​</a></h2><ul><li><code>근위</code> / <code>돌격</code> / <code>궁수</code>를 세계 병과로 승격</li><li>활·석궁을 기본 원거리</li><li>떠돌이 시작 권총</li><li>서기 붕괴 연도를 정본처럼 단정</li><li>폴아웃·호라이즌 고유명을 공개 카피에 심기</li></ul><h2 id="아직-잠그지-않은-것" tabindex="-1">아직 잠그지 않은 것 <a class="header-anchor" href="#아직-잠그지-않은-것" aria-label="Permalink to &quot;아직 잠그지 않은 것&quot;">​</a></h2><ul><li>붕괴의 AD 연도</li><li>군용 잔존의 모델명. 공개면은 「제식 소화기」로 충분하다. 장부가 어디에 있는지는 <a href="/world/Conscription-Remnants.html">징집 잔존과 군 장부</a></li><li>단발 관형 발사기를 P0에 둘지. 정본 프리셋은 봉·방패까지다</li><li>물자점 부품을 강재·체결·스프링으로 나눌지</li></ul><p>조사 원장: 저장소 <code>.omo/ulw-research/20260911-200129/</code></p>',39)])])}const b=d(o,[["render",h]]);export{m as __pageData,b as default};
